window.OVERDRIVE_CONTENT = {"news": [{"id": "apex", "category": "Racing", "date": "07.10.2026", "iso": "2026-10-07", "title": "Die nächste Runde beginnt.", "teaser": "Apex Championship: ein neues Format. Eine gemeinsame Startlinie. Und alles, was danach zählt.", "image": "hero", "read": "4 Min.", "paragraphs": ["Ein Wochenende, vier Strecken und ein gemeinsames Ziel: saubere Duelle bis zur letzten Kurve. Die Apex Championship ist das Turnierkonzept unserer Overdrive-Demo. Hier zeigen wir, wie Ankündigungen, Informationen und Anmeldungen in einem späteren Community-Auftritt zusammenspielen können.", "Das Format beginnt mit einem offenen Qualifying. Danach fahren die Teams in zwei Klassen um ihre Platzierung. Gleiche Bedingungen und eine nachvollziehbare Wertung stehen dabei im Mittelpunkt.", "Zwischen den Rennen bleibt Zeit für Setup-Gespräche, Streckenanalysen und gemeinsame Trainings. Die Turnierseite enthält den Beispielablauf und einen Kalenderdownload. Alle Termine, Teams und Ergebnisse dieser Website sind Demo-Inhalte."]}, {"id": "nexus", "category": "Community", "date": "05.10.2026", "iso": "2026-10-05", "title": "Inside Nexus: mehr als schnelle Runden.", "teaser": "Drei Fahrer. Ein Rhythmus. Wie aus einzelnen Talenten ein eingespieltes Team wird.", "image": "nexus", "read": "3 Min.", "paragraphs": ["Konstanz entsteht im Team. Für das fiktive Nexus Racing beginnt ein guter Rennabend deshalb lange vor dem Start: mit gemeinsamem Training und einer klaren Aufgabenverteilung.", "Während eine Person die Telemetrie auswertet, testen die anderen verschiedene Linien und Bremspunkte. Erst wenn sich ein Setup für alle nachvollziehbar anfühlt, geht es in den längeren Stint.", "Die Teamprofile dieser Testwebsite zeigen, wie Fahrer, Disziplinen und Informationen präsentiert werden können. Namen und Porträts sind illustrative Demo-Inhalte; die Bilder wurden KI-gestützt erstellt."]}, {"id": "nightshift", "category": "Garage", "date": "03.10.2026", "iso": "2026-10-03", "title": "Night Shift. Eine Garage voller Ideen.", "teaser": "Carbon, Werkstattlicht und der Blick fürs Detail: die Bildwelt hinter Overdrive.", "image": "garage", "read": "5 Min.", "paragraphs": ["Overdrive verbindet digitale Rennkultur mit der Atmosphäre einer echten Werkstatt. Dunkle Oberflächen, klare Typografie und wenige rote Akzente geben den Motiven ihren Rahmen.", "Die Website verwendet eigenständige Bilddateien. Navigation, Texte, Buttons und Inhaltskarten sind echte HTML-Elemente. Dadurch bleiben Inhalte austauschbar und passen sich verschiedenen Bildschirmgrößen an.", "Dieser Artikel ist ein Beispiel für die spätere redaktionelle Nutzung des Templates. Im Testprojekt werden die Inhalte lokal gepflegt. Eine CMS-Anbindung, Mitgliederkonten und ein E-Mail-Versand sind noch nicht Bestandteil dieser Ausgabe."]}, {"id": "touge", "category": "Racing", "date": "01.10.2026", "iso": "2026-10-01", "title": "Grip, Präzision und die perfekte Linie.", "teaser": "Unser Drift-Special über kontrollierte Bewegung und die Faszination nächtlicher Strecken.", "image": "drift", "read": "3 Min.", "paragraphs": ["Im virtuellen Motorsport treffen Reaktion, Technik und Rhythmus aufeinander. Das Drift-Special unseres Demo-Magazins greift diese Energie mit einer eigenen Bildstrecke auf.", "Die Strecke wird Runde für Runde vertrauter. Ein klarer Einlenkpunkt und die richtige Balance machen aus einzelnen Bewegungen einen flüssigen Ablauf.", "Alle dargestellten Wettbewerbe sind fiktiv und beziehen sich auf das Testprojekt. Die Motive dienen als Beispiel dafür, wie eine Racing-Community redaktionelle Themen visuell erzählen kann."]}], "teams": [{"id": "velocity", "name": "Velocity Racing", "division": "Simracing", "image": "velocity", "tag": "SPEED UNITES US", "symbol": "V", "members": ["Alex Storm", "Mia Novak", "Leon Cross"], "description": "Präzise Linien. Ruhige Köpfe. Velocity verbindet schnelle Einzelrunden mit der Konstanz eines eingespielten Teams."}, {"id": "shadow", "name": "Shadow Motorsport", "division": "Drift", "image": "drift", "tag": "OWN THE NIGHT", "symbol": "S", "members": ["Kai Reed", "Lena Voss", "Noah Blake"], "description": "Das Drift-Team der Demo: kontrollierte Bewegung, saubere Übergänge und ein Gespür für die perfekte Balance."}, {"id": "nexus", "name": "Nexus Racing", "division": "Endurance", "image": "nexus", "tag": "PEOPLE. PERFORMANCE. PROGRESS.", "symbol": "N", "members": ["Jules Hart", "Sam Vale", "Amir Cole"], "description": "Ausdauer ist Teamarbeit. Nexus steht für gemeinsame Vorbereitung, klare Absprachen und konstante Stints."}, {"id": "rapidfire", "name": "Rapidfire Garage", "division": "Simracing", "image": "garage", "tag": "MORE THAN A GAME", "symbol": "R", "members": ["Finn Archer", "Eva Lane", "Ben Frost"], "description": "Setup-Kultur trifft Rennleidenschaft. Rapidfire bringt die Werkstattmentalität auf die virtuelle Strecke."}]};